// Procedural canyon terrain. Everything is periodic in z with period P so the
// camera can loop forever. Terrain is described in canyon-relative coordinates
// (u = lateral offset from the winding centre line, z = along the canyon).

export const P = 512;
export const TAU = Math.PI * 2;

// Unit vector pointing toward the sun (low, ahead and to the side).
const sl = Math.hypot(0.55, 0.2, 0.81);
export const SUN: [number, number, number] = [0.55 / sl, 0.2 / sl, 0.81 / sl];

export const U_MAX = 75;

function hash2(i: number, j: number): number {
  let h = Math.imul(i, 374761393) ^ Math.imul(j, 668265263);
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  h ^= h >>> 16;
  return (h >>> 0) / 4294967296;
}

// Value noise, periodic in z with `pz` cells.
function vn(x: number, z: number, pz: number, seed: number): number {
  const xi = Math.floor(x);
  const zi = Math.floor(z);
  const fx = x - xi;
  const fz = z - zi;
  const sx = fx * fx * (3 - 2 * fx);
  const sz = fz * fz * (3 - 2 * fz);
  const z0 = ((zi % pz) + pz) % pz;
  const z1 = (z0 + 1) % pz;
  const o = seed * 1000;
  const a = hash2(xi, z0 + o);
  const b = hash2(xi + 1, z0 + o);
  const c = hash2(xi, z1 + o);
  const d = hash2(xi + 1, z1 + o);
  return a + (b - a) * sx + (c - a) * sz + (a - b - c + d) * sx * sz;
}

function sstep(a: number, b: number, x: number): number {
  const t = Math.min(1, Math.max(0, (x - a) / (b - a)));
  return t * t * (3 - 2 * t);
}

function wrapZ(z: number): number {
  return ((z % P) + P) % P;
}

/** x of the canyon centre line at z. */
export function cl(z: number): number {
  const a = (TAU * z) / P;
  return 16 * Math.sin(2 * a) + 4.5 * Math.sin(5 * a + 1) + 1.2 * Math.sin(9 * a + 2);
}

export function clSlope(z: number): number {
  const a = (TAU * z) / P;
  return (32 * Math.cos(2 * a) + 22.5 * Math.cos(5 * a + 1) + 10.8 * Math.cos(9 * a + 2)) * (TAU / P);
}

/** Lateral drift of the camera relative to the centre line. */
export function camU(z: number): number {
  const a = (TAU * z) / P;
  return 3.2 * Math.sin(7 * a + 0.5) + 1.4 * Math.sin(13 * a + 2);
}

function floorH(u: number, z: number): number {
  const f = (vn(u / 16, z / 16, 32, 1) - 0.5) * 0.9 + (vn(u / 4, z / 4, 128, 2) - 0.5) * 0.25;
  const a = (TAU * z) / P;
  const rc = 4 * Math.sin(6 * a + 0.7) + 2 * Math.sin(11 * a);
  const q = (u - rc) / 3.2;
  return f - 0.8 * Math.exp(-q * q);
}

export function height(u: number, zIn: number): number {
  const z = wrapZ(zIn);
  const a = (TAU * z) / P;
  const right = u >= 0;
  const w = right
    ? 13 + 3.5 * Math.sin(3 * a + 2) + 2 * Math.sin(7 * a)
    : 13 + 3.5 * Math.sin(3 * a + 4) + 2 * Math.sin(8 * a + 1);
  const au = Math.abs(u);
  const dd = au + (vn(u / 16, z / 16, 32, 3) - 0.5) * 12 + (vn(u / 8, z / 8, 64, 4) - 0.5) * 3.5;
  const t = dd - w;
  const h = floorH(u, z);
  if (t <= 0) return h;

  const rim = 20 + 16 * vn(au / 32 + (right ? 0 : 11.5), z / 32, 16, 5);
  const r = Math.min(t / 16, 1);
  let hp = rim * (1 - Math.pow(1 - r, 2.2));

  // sandstone terraces: flat ledges separated by steep risers
  const step = 3 + 1.8 * vn(0.5, z / 64, 8, 6);
  const s = hp / step;
  const fl = Math.floor(s);
  const ss = sstep(0.4, 1, s - fl);
  hp = hp * 0.2 + (fl + ss) * step * 0.8;

  // rolling mesa top
  hp += (t > 16 ? (t - 16) * 0.05 : 0);
  hp += (vn(au / 24 + 3, z / 24, 21.333 === 0 ? 1 : 32 / 1.5 | 0 || 1, 9) - 0.5) * 0;
  hp += (vn(au / 16 + 3, z / 16, 32, 9) - 0.5) * 8 * sstep(10, 22, t);

  // surface roughness
  hp += ((vn(u / 4, z / 4, 128, 7) - 0.5) * 1.4 + (vn(u / 2, z / 2, 256, 8) - 0.5) * 0.6) * Math.min(1, t / 3);
  return h + hp;
}

// ---- raster copy of the height field, used for sun shadow ray marching ----
const GN = P;
const GU = U_MAX * 2 + 1;
let grid: Float32Array | null = null;

function buildGrid(): Float32Array {
  const g = new Float32Array(GU * GN);
  for (let k = 0; k < GN; k++) {
    for (let i = 0; i < GU; i++) {
      g[k * GU + i] = height(i - U_MAX, k);
    }
  }
  return g;
}

function sampleGrid(u: number, z: number): number {
  const g = grid as Float32Array;
  const uu = Math.min(GU - 1.001, Math.max(0, u + U_MAX));
  const zz = wrapZ(z);
  const i = Math.floor(uu);
  const k = Math.floor(zz);
  const fu = uu - i;
  const fz = zz - k;
  const k1 = (k + 1) % GN;
  const a = g[k * GU + i];
  const b = g[k * GU + i + 1];
  const c = g[k1 * GU + i];
  const d = g[k1 * GU + i + 1];
  return a + (b - a) * fu + (c - a) * fz + (a - b - c + d) * fu * fz;
}

/** Soft sun visibility (0 = shadowed, 1 = lit) for a world-space point. */
export function sunShadow(x: number, y: number, z: number): number {
  if (!grid) grid = buildGrid();
  let res = 1;
  let s = 0;
  let stepLen = 0.5;
  for (let i = 0; i < 56; i++) {
    s += stepLen;
    stepLen *= 1.07;
    const pz = z + SUN[2] * s;
    const py = y + SUN[1] * s;
    if (py > 75) break;
    const px = x + SUN[0] * s;
    const hh = sampleGrid(px - cl(pz), pz);
    const d = (py - hh) / (0.07 * s + 0.3);
    if (d < res) res = d;
    if (res <= 0) return 0;
  }
  const t = Math.min(1, Math.max(0, res));
  return t * t * (3 - 2 * t);
}

export function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

import * as THREE from 'three';
import { SUN } from './terrain';

const f = (n: number) => n.toFixed(5);

// Shared GLSL: sky gradient in display (sRGB) space. The same function is used
// for the sky dome and for the haze colour on geometry, so distant walls fade
// into the sky.
const SKY_GLSL = /* glsl */ `
const vec3 SUNDIR = vec3(${f(SUN[0])}, ${f(SUN[1])}, ${f(SUN[2])});
vec3 skyColor(vec3 d) {
  float t = max(d.y, 0.0);
  vec3 hor = vec3(0.86, 0.50, 0.50);
  vec3 mid = vec3(0.50, 0.36, 0.62);
  vec3 zen = vec3(0.10, 0.14, 0.42);
  vec3 c = mix(hor, mid, smoothstep(0.0, 0.22, t));
  c = mix(c, zen, smoothstep(0.15, 0.75, t));
  float sd = max(dot(normalize(d), SUNDIR), 0.0);
  float fall = exp(-t * 3.0);
  c += vec3(1.0, 0.45, 0.16) * pow(sd, 5.0) * 0.55 * fall;
  c += vec3(1.0, 0.30, 0.38) * pow(sd, 24.0) * 0.5 * fall;
  return c;
}
`;

export function makeNoiseTexture(rng: () => number): THREE.DataTexture {
  const n = 64;
  const data = new Uint8Array(n * n * 4);
  for (let i = 0; i < data.length; i++) data[i] = Math.floor(rng() * 256);
  const tex = new THREE.DataTexture(data, n, n, THREE.RGBAFormat);
  tex.wrapS = THREE.RepeatWrapping;
  tex.wrapT = THREE.RepeatWrapping;
  tex.magFilter = THREE.LinearFilter;
  tex.minFilter = THREE.LinearMipmapLinearFilter;
  tex.generateMipmaps = true;
  tex.needsUpdate = true;
  return tex;
}

const TERRAIN_COLOR = /* glsl */ `
#include <color_fragment>
{
  vec2 q = vWPos.xz / 512.0;
  float n1 = texture2D(uNoise, q * 1.0).r;
  float n2 = texture2D(uNoise, q * 4.0 + 0.37).r;
  float n3 = texture2D(uNoise, q * 16.0 + 0.71).r;
  float n4 = texture2D(uNoise, q * 64.0 + 0.13).r;
  float streak = texture2D(uNoise, vec2((vWPos.x + vWPos.z) / 512.0 * 24.0, vWPos.y / 512.0 * 2.0)).r;

  float y = vWPos.y + (n1 - 0.5) * 4.0 + (n2 - 0.5) * 1.5;
  float ia = floor(y * 0.09);
  vec3 st = strataPalette(hash11(ia * 1.7 + 3.0));
  st *= 0.85 + 0.30 * hash11(floor(y * 0.7) + 11.0);
  st *= 0.94 + 0.12 * hash11(floor(y * 2.3) + 5.0);
  st *= 0.82 + 0.36 * mix(n3, n4, 0.5);
  st *= 0.82 + 0.36 * streak;
  st *= 1.0 - 0.35 * (1.0 - smoothstep(0.0, 0.10, fract(y * 0.7)));

  vec3 sand = mix(vec3(0.74, 0.56, 0.40), vec3(0.62, 0.45, 0.34), n2);
  sand *= 0.85 + 0.30 * n3;
  sand *= 0.92 + 0.16 * n4;
  float riv = smoothstep(-0.15, -0.55, vWPos.y);
  sand = mix(sand, vec3(0.86, 0.74, 0.58) * (0.9 + 0.2 * n4), riv * 0.7);
  sand = mix(sand, st, 0.2);

  float dust = smoothstep(0.78, 0.93, vWNrm.y);
  vec3 col = mix(st, sand, dust * 0.9);
  diffuseColor.rgb = pow(col, vec3(2.2));
}
`;

const TERRAIN_PARS = /* glsl */ `
float hash11(float p) { return fract(sin(p * 127.1) * 43758.5453); }
vec3 strataPalette(float h) {
  vec3 c0 = vec3(0.50, 0.20, 0.12);
  vec3 c1 = vec3(0.78, 0.40, 0.20);
  vec3 c2 = vec3(0.80, 0.58, 0.38);
  vec3 c3 = vec3(0.62, 0.33, 0.26);
  vec3 c4 = vec3(0.86, 0.70, 0.50);
  h *= 4.0;
  if (h < 1.0) return mix(c0, c1, h);
  if (h < 2.0) return mix(c1, c2, h - 1.0);
  if (h < 3.0) return mix(c2, c3, h - 2.0);
  return mix(c3, c4, h - 3.0);
}
`;

/**
 * Adds to a MeshStandardMaterial: per-vertex baked sun shadow (attribute
 * `bake`), sun-aware haze, and for terrain a procedural strata colour.
 */
export function patchMaterial(mat: THREE.MeshStandardMaterial, kind: 'terrain' | 'prop', noise: THREE.Texture): void {
  mat.customProgramCacheKey = () => 'canyon-' + kind;
  mat.onBeforeCompile = (shader) => {
    shader.uniforms.uNoise = { value: noise };

    shader.vertexShader = shader.vertexShader
      .replace(
        '#include <common>',
        `#include <common>
attribute float bake;
varying float vBake;
varying vec3 vWPos;
varying vec3 vWNrm;`,
      )
      .replace(
        '#include <project_vertex>',
        `#include <project_vertex>
vBake = bake;
vWPos = (modelMatrix * vec4(transformed, 1.0)).xyz;
vWNrm = objectNormal;`,
      );

    let frag = shader.fragmentShader.replace(
      '#include <common>',
      `#include <common>
uniform sampler2D uNoise;
varying float vBake;
varying vec3 vWPos;
varying vec3 vWNrm;
${SKY_GLSL}
${kind === 'terrain' ? TERRAIN_PARS : ''}`,
    );
    if (kind === 'terrain') {
      frag = frag.replace('#include <color_fragment>', TERRAIN_COLOR);
    }
    frag = frag
      .replace(
        '#include <aomap_fragment>',
        `#include <aomap_fragment>
reflectedLight.directDiffuse *= vBake;
reflectedLight.directSpecular *= vBake;`,
      )
      .replace(
        '#include <fog_fragment>',
        `#ifdef USE_FOG
{
  float fogF = 1.0 - exp(-fogDensity * fogDensity * vFogDepth * vFogDepth);
  vec3 vd = normalize(vWPos - cameraPosition);
  vd.y = min(vd.y, 0.12);
  gl_FragColor.rgb = mix(gl_FragColor.rgb, skyColor(vd), fogF);
}
#endif`,
      );
    shader.fragmentShader = frag;
  };
}

export function makeSky(): THREE.Mesh {
  const mat = new THREE.ShaderMaterial({
    side: THREE.BackSide,
    depthWrite: false,
    fog: false,
    vertexShader: /* glsl */ `
varying vec3 vDir;
void main() {
  vDir = position;
  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}`,
    fragmentShader: /* glsl */ `
varying vec3 vDir;
${SKY_GLSL}
void main() {
  vec3 d = normalize(vDir);
  vec3 c = skyColor(d);
  float sd = dot(d, SUNDIR);
  float disc = smoothstep(0.99955, 0.99985, sd);
  c = mix(c, vec3(1.0, 0.86, 0.62), disc);
  float n = fract(sin(dot(gl_FragCoord.xy, vec2(12.9898, 78.233))) * 43758.5453);
  c += (n - 0.5) / 255.0;
  gl_FragColor = vec4(c, 1.0);
}`,
  });
  const mesh = new THREE.Mesh(new THREE.SphereGeometry(800, 48, 24), mat);
  mesh.frustumCulled = false;
  mesh.renderOrder = -1;
  return mesh;
}

import * as THREE from 'three';
import { mergeGeometries } from 'three/examples/jsm/utils/BufferGeometryUtils.js';
import { P, cl, camU, height, sunShadow } from './terrain';

function addBake(g: THREE.BufferGeometry, value: number): void {
  const n = g.getAttribute('position').count;
  g.setAttribute('bake', new THREE.BufferAttribute(new Float32Array(n).fill(value), 1));
}

/** Pick a floor position that stays clear of the camera's flight path. */
function pickSpot(rng: () => number, clearance: number): { u: number; z: number } {
  for (let tries = 0; tries < 50; tries++) {
    const z = 8 + rng() * (P - 16);
    const u = (rng() * 2 - 1) * 11;
    if (Math.abs(u - camU(z)) > clearance) return { u, z };
  }
  return { u: 11, z: 8 + rng() * (P - 16) };
}

export function buildBoulders(rng: () => number, count: number): THREE.BufferGeometry {
  const base = new THREE.IcosahedronGeometry(1, 2);
  base.deleteAttribute('uv');
  const parts: THREE.BufferGeometry[] = [];
  const color = new THREE.Color();

  for (let i = 0; i < count; i++) {
    const r = 0.35 + 3.2 * Math.pow(rng(), 3);
    const { u, z } = pickSpot(rng, r + 3);
    const g = base.clone();
    const pos = g.getAttribute('position') as THREE.BufferAttribute;
    const seed = rng() * 100;
    for (let k = 0; k < pos.count; k++) {
      const x = pos.getX(k);
      const y = pos.getY(k);
      const zz = pos.getZ(k);
      const d =
        1 + 0.18 * Math.sin(x * 2.3 + seed) * Math.cos(y * 2.9 + seed * 1.7) + 0.1 * Math.sin(zz * 5.1 + x * 3.7 + seed * 0.6);
      pos.setXYZ(k, x * d, y * d, zz * d);
    }
    g.computeVertexNormals();

    const tint = 0.75 + rng() * 0.45;
    const redness = rng();
    const colors = new Float32Array(pos.count * 3);
    for (let k = 0; k < pos.count; k++) {
      const shade = 0.7 + 0.3 * (pos.getY(k) * 0.5 + 0.5);
      color.setRGB(
        (0.5 + 0.1 * redness) * tint * shade,
        (0.33 + 0.02 * redness) * tint * shade,
        0.25 * tint * shade,
        THREE.SRGBColorSpace,
      );
      colors[k * 3] = color.r;
      colors[k * 3 + 1] = color.g;
      colors[k * 3 + 2] = color.b;
    }
    g.setAttribute('color', new THREE.BufferAttribute(colors, 3));

    const sx = r * (0.9 + rng() * 0.5);
    const sy = r * (0.55 + rng() * 0.35);
    const sz = r * (0.9 + rng() * 0.5);
    const gy = height(u, z);
    const wx = cl(z) + u;
    const m = new THREE.Matrix4().compose(
      new THREE.Vector3(wx, gy + sy * 0.4, z),
      new THREE.Quaternion().setFromEuler(new THREE.Euler((rng() - 0.5) * 0.3, rng() * Math.PI * 2, (rng() - 0.5) * 0.3)),
      new THREE.Vector3(sx, sy, sz),
    );
    g.applyMatrix4(m);
    addBake(g, sunShadow(wx, gy + sy * 0.9, z));
    parts.push(g);
  }
  const merged = mergeGeometries(parts, false);
  if (!merged) throw new Error('boulder merge failed');
  parts.forEach((p) => p.dispose());
  return merged;
}

function shrubVariant(rng: () => number): THREE.BufferGeometry {
  const parts: THREE.BufferGeometry[] = [];
  const up = new THREE.Vector3(0, 1, 0);

  const branch = (start: THREE.Vector3, dir: THREE.Vector3, len: number, rad: number, depth: number): void => {
    const g = new THREE.CylinderGeometry(rad * 0.62, rad, len, 3, 1);
    g.translate(0, len / 2, 0);
    g.applyMatrix4(
      new THREE.Matrix4().compose(start, new THREE.Quaternion().setFromUnitVectors(up, dir), new THREE.Vector3(1, 1, 1)),
    );
    g.deleteAttribute('uv');
    parts.push(g);
    if (depth <= 0) return;
    const end = start.clone().addScaledVector(dir, len);
    for (let k = 0; k < 2; k++) {
      const d2 = dir
        .clone()
        .add(new THREE.Vector3(rng() - 0.5, (rng() - 0.3) * 0.6, rng() - 0.5).multiplyScalar(1.3))
        .normalize();
      branch(end, d2, len * (0.62 + rng() * 0.2), rad * 0.6, depth - 1);
    }
  };

  const trunks = 5 + Math.floor(rng() * 3);
